package com.shopsphere;import static org.junit.jupiter.api.Assertions.*;import java.math.BigDecimal;import java.util.*;import org.junit.jupiter.api.*;class OrderServiceTest{static class Inventory implements InventoryGateway{int reserved;public synchronized void reserve(UUID id,int q){reserved+=q;}public synchronized void release(UUID id,int q){reserved-=q;}}Inventory inventory;OrderRepository.InMemory repo;OrderService service;OrderDtos.Create request;@BeforeEach void set(){inventory=new Inventory();repo=new OrderRepository.InMemory();service=new OrderService(repo,inventory,new OrderIdempotencyStore.InMemory(),i->new ProductPricingGateway.PricedProduct(i.productId(),"Catalog name","CATALOG-SKU",BigDecimal.valueOf(1000),true));request=new OrderDtos.Create(UUID.randomUUID(),List.of(new OrderDtos.Item(UUID.randomUUID(),"Nova","SKU-1",BigDecimal.valueOf(1000),2)),BigDecimal.valueOf(100),BigDecimal.valueOf(50),new OrderDtos.AddressRequest("Aarav","1 Main",null,"Bengaluru","Karnataka","560001","India","9999999999"));}@Test void createsOrderAndCalculatesTotal(){Order o=service.create("key-create",request);assertEquals(BigDecimal.valueOf(2000),o.subtotal());assertEquals(BigDecimal.valueOf(2000),o.totalAmount());assertEquals(Order.Status.CONFIRMED,o.status());assertEquals(2,inventory.reserved);}@Test void enforcesTransitionsAndCancellation(){Order o=service.create("key-cancel",request);Order processing=service.status(o.id(),Order.Status.PROCESSING);assertEquals(Order.Status.PROCESSING,processing.status());Order cancelled=service.cancel(o.id());assertEquals(Order.Status.CANCELLED,cancelled.status());assertEquals(0,inventory.reserved);assertThrows(BusinessException.class,()->service.status(o.id(),Order.Status.DELIVERED));}
@Test void sameKeyAndRequestReturnsSameOrderWithoutDoubleReservation(){Order first=service.create("stable-key",request);Order second=service.create("stable-key",request);assertEquals(first.id(),second.id());assertEquals(1,repo.findByUser(request.userId()).size());assertEquals(2,inventory.reserved);}@Test void sameKeyDifferentRequestConflicts(){service.create("conflict-key",request);var changed=new OrderDtos.Create(request.userId(),List.of(new OrderDtos.Item(request.items().getFirst().productId(),"Nova","SKU-1",BigDecimal.valueOf(1000),3)),request.discount(),request.deliveryFee(),request.shippingAddress());assertThrows(IdempotencyConflictException.class,()->service.create("conflict-key",changed));assertEquals(1,repo.findByUser(request.userId()).size());assertEquals(2,inventory.reserved);}@Test void missingKeyIsRejected(){assertThrows(MissingIdempotencyKeyException.class,()->service.create(null,request));}@Test void concurrentDuplicateCreatesOneLogicalOrder()throws Exception{var start=new java.util.concurrent.CountDownLatch(1);var pool=java.util.concurrent.Executors.newFixedThreadPool(2);var calls=java.util.stream.IntStream.range(0,2).mapToObj(i->pool.submit(()->{start.await();try{return service.create("concurrent-key",request).id();}catch(IdempotencyInProgressException expected){return null;}})).toList();start.countDown();for(var call:calls)call.get();pool.shutdown();assertEquals(1,repo.findByUser(request.userId()).size());assertEquals(2,inventory.reserved);}@Test void orderNumbersRemainUniqueAcrossServiceInstances(){Order one=service.create("restart-one",request);var restarted=new OrderService(repo,inventory,new OrderIdempotencyStore.InMemory(),i->new ProductPricingGateway.PricedProduct(i.productId(),"Catalog name","CATALOG-SKU",BigDecimal.valueOf(1000),true));var secondRequest=new OrderDtos.Create(request.userId(),List.of(new OrderDtos.Item(UUID.randomUUID(),"Two","SKU-2",BigDecimal.TEN,1)),BigDecimal.ZERO,BigDecimal.ZERO,request.shippingAddress());Order two=restarted.create("restart-two",secondRequest);assertNotEquals(one.orderNumber(),two.orderNumber());assertTrue(one.orderNumber().startsWith("SS-"));}}
